// 注入系统提示词（workflows/prompts/mobo-capital-synthesis-prompt.md）
// 输出：{ system, user }
const body = $input.first().json;
const source = body.data || body.content || '';
const system = $('Webhook_合成').first().json.system_prompt
  || '你是莫伯资本的首席投研总编与合规风控官。只返回合法 JSON，字段：slug, web_markdown, wechat_html, xueqiu_markdown, x_thread_json。境内版本必须脱敏具体买卖点位并附免责声明。';
const user = `标题：${body.title || ''}\n类别：${body.category || 'MACRO'}\n\n母本：\n${String(source).slice(0, 12000)}`;
return [{ json: { system, user, title: body.title || '未命名', category: body.category || 'MACRO' } }];

// 严格解析四端 JSON；解析失败 -> NEEDS_MANUAL
const raw = $json?.choices?.[0]?.message?.content ?? '';
let parsed = {};
try {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  parsed = JSON.parse(s >= 0 && e > s ? raw.slice(s, e + 1) : raw);
} catch (err) {
  return [{ json: { parse_error: String(err), raw: raw.slice(0, 500) } }];
}
const slug = (parsed.slug || 'memo-' + Date.now()).toString();
return [{
  json: {
    slug,
    web_markdown: parsed.web_markdown || '',
    wechat_html: parsed.wechat_html || '',
    xueqiu_markdown: parsed.xueqiu_markdown || '',
    x_thread_json: Array.isArray(parsed.x_thread_json) ? parsed.x_thread_json : []
  }
}];

// 人工批准后：准备四端 payload（内容来自已入库的 capital_publications）
const body = $input.first().json;
const rec = body.body || body;
return {
  json: {
    slug: rec.slug,
    title: rec.title,
    wechat_html: rec.wechat_html || '',
    x_thread_json: rec.x_thread_json || []
  }
};

// X 链式串推：逻辑见 workflows/nodes/x-thread-publish.code.js
// 需在 n8n 中配置 twitterOAuth2Api 凭证；未配置时保持本节点禁用
const threadArray = $input.first().json.x_thread_json || [];
if (!threadArray.length) {
  return [{ json: { skipped: true, reason: 'no thread payload' } }];
}
let previousTweetId = null;
const publishedTweetIds = [];
for (let i = 0; i < threadArray.length; i++) {
  const payload = { text: String(threadArray[i]).slice(0, 260) };
  if (previousTweetId) {
    payload.reply = { in_reply_to_tweet_id: previousTweetId };
  }
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'twitterOAuth2Api',
    { method: 'POST', url: 'https://api.twitter.com/2/tweets', body: payload, json: true }
  );
  previousTweetId = response.data.id;
  publishedTweetIds.push(previousTweetId);
  await new Promise(resolve => setTimeout(resolve, 1500));
}
return [{ json: { x_root_tweet_id: publishedTweetIds[0], x_thread_count: publishedTweetIds.length, x_thread_url: 'https://x.com/i/web/status/' + publishedTweetIds[0] } }];
